<!-- signing.html --><!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no"/><title>Umu-Oyi — Secure Signing</title><link id="siteFavicon" rel="icon" href="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='128' height='128' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%23ffd966'/><stop offset='1' stop-color='%236a1b9a'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%230f0b16'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/><text x='64' y='86' font-family='Inter, Arial, sans-serif' font-size='18' font-weight='700' text-anchor='middle' fill='%23ffffff'>Umu-Oyi</text></svg>"/><link rel="manifest" href="/manifest.json"/><link rel="apple-touch-icon" sizes="180x180" href="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%23ffd966'/><stop offset='1' stop-color='%236a1b9a'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%230f0b16'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/><text x='64' y='86' font-family='Inter, Arial, sans-serif' font-size='18' font-weight='700' text-anchor='middle' fill='%23ffffff'>Umu-Oyi</text></svg>"/><link rel="mask-icon" href="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%23ffd966'/><stop offset='1' stop-color='%236a1b9a'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%230f0b16'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/></svg>" color="#6a1b9a"/><meta name="theme-color" content="#0f0b16"/><meta name="description" content="Umu-Oyi — Secure signing for Umugwuanyi-Oyi family members. Access private archives and features."/><link id="mainCss" rel="stylesheet" href="signing-light.css"/></head><body><div id="loader" class="loader"><div class="loader-ring"><div class="loader-ring-inner"></div></div><div class="loader-text">Authenticating Legacy...</div></div><header class="site-header"><div class="container header-inner"><div class="brand"><a href="index.html"><img id="siteLogo" src="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='128' height='128' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%23ffd966'/><stop offset='1' stop-color='%236a1b9a'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%230f0b16'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/><text x='64' y='86' font-family='Inter, Arial, sans-serif' font-size='18' font-weight='700' text-anchor='middle' fill='%23ffffff'>Umu-Oyi</text></svg>" alt="Umu-Oyi Logo" class="logo"/></a><div class="brand-text"><h1 id="brandTitle">Umu-Oyi Signing</h1><p class="sub" id="brandSub">Access Eternal Heritage · Amama Village · Ede-Oballa · Nsukka · Enugu</p></div></div><nav class="nav"><a href="index.html" class="nav-link" id="navHome">Home</a><a href="signup.html" class="nav-link" id="navSignup">Signup</a><a href="index.html#contact" class="nav-link" id="navContact">Contact</a><button id="langToggle" class="lang">Igbo</button><button id="themeToggle" class="lang">Theme</button></nav></div></header><main><section class="hero"><div class="container hero-inner"><div class="hero-text"><h2 id="heroTitle">Secure Signing Portal</h2><p id="heroDesc">Enter the inner sanctum of Umu-Oyi. Authenticate securely to access detailed family archives, interactive tree with DOB sorting, photo galleries, and contribution tools. Featuring biometric options, 2FA, and AI-assisted recovery.</p><div class="hero-actions"><a href="#login" id="btnLogin" class="btn">Sign In</a><a href="#forgot" id="btnForgot" class="ghost">Forgot Password?</a></div></div><div class="hero-art"><div class="royal-crest"><svg viewBox="0 0 300 300" class="crest-svg"><defs><linearGradient id="crestGrad" x1="0" x2="1" y1="0" y2="1"><stop offset="0%" stop-color="#ffd966"/><stop offset="100%" stop-color="#6a1b9a"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="3" result="coloredBlur"/><feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><circle cx="150" cy="150" r="120" fill="url(#crestGrad)" filter="url(#glow)"/><text x="150" y="160" text-anchor="middle" font-size="28" fill="#ffffff" font-family="serif" font-weight="bold">Signing</text></svg></div></div></div><div class="hero-bg-animation"></div></section><section id="login" class="container login-section"><h3 id="loginTitle">Sign In to Your Legacy</h3><p id="loginDesc">Use your credentials to access private features. Enable 2FA for enhanced security.</p><form class="login-form" id="loginForm"><input id="loginEmail" type="email" placeholder="Your Email" required/><input id="loginPassword" type="password" placeholder="Password" required/><input id="loginOtp" type="text" placeholder="2FA Code (if enabled)" class="hidden"/><label class="checkbox"><input type="checkbox" id="rememberMe"/> <span id="rememberLabel">Remember Me</span></label><button id="loginSubmit" type="submit" class="btn">Secure Sign In</button><div id="formLoader" class="form-loader hidden"><div class="loader-ring-small"><div class="loader-ring-inner"></div></div></div></form><div id="loginStatus" class="status-message"></div><div class="biometric-option"><button id="biometricBtn" class="ghost">Use Biometrics</button></div></section><section id="forgot" class="container forgot-section"><h3 id="forgotTitle">Recover Access</h3><p id="forgotDesc">Enter your email for a secure reset link. AI will assist in verification.</p><form class="forgot-form" id="forgotForm"><input id="forgotEmail" type="email" placeholder="Your Email" required/><button id="forgotSubmit" type="submit" class="btn">Send Reset Link</button></form><div id="forgotStatus" class="status-message"></div></section><section class="container cta-footer"><div class="cta-inner"><h4 id="footerCta">New to Umu-Oyi?</h4><p id="footerCtaDesc">Create an account to join the legacy.</p><a id="footerSignup" href="signup.html" class="btn">Sign Up Now</a></div></section></main><footer class="site-footer"><div class="container footer-inner"><div>© <span id="year"></span> Umu-Oyi Family Heritage Archive · Built by Master Chukwuemeka Onah Henry</div><div class="foot-links"><a href="/privacy.html">Privacy Policy</a><a href="/terms.html">Terms of Use</a><a href="#top">Back to Top</a></div></div></footer><script>document.getElementById('year').textContent=new Date().getFullYear();(function(){const lightSvg="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='128' height='128' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%23ffd966'/><stop offset='1' stop-color='%236a1b9a'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%230f0b16'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/><text x='64' y='86' font-family='Inter, Arial, sans-serif' font-size='18' font-weight='700' text-anchor='middle' fill='%23ffffff'>Umu-Oyi</text></svg>",darkSvg="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='128' height='128' viewBox='0 0 128 128'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%236a1b9a'/><stop offset='1' stop-color='%23ffd966'/></linearGradient></defs><rect width='128' height='128' rx='20' fill='%23ffffff'/><circle cx='64' cy='44' r='28' fill='url(%23g)'/><text x='64' y='86' font-family='Inter, Arial, sans-serif' font-size='18' font-weight='700' text-anchor='middle' fill='%230f0b16'>Umu-Oyi</text></svg>",css=document.getElementById('mainCss'),logo=document.getElementById('siteLogo'),icon=document.getElementById('siteFavicon'),btn=document.getElementById('themeToggle');let theme=localStorage.getItem('siteTheme')||'light';function applyTheme(t){theme=t||theme;theme==='dark'?(css.setAttribute('href','signing-dark.css'),logo.setAttribute('src',darkSvg),icon.setAttribute('href',darkSvg)):(css.setAttribute('href','signing-light.css'),logo.setAttribute('src',lightSvg),icon.setAttribute('href',lightSvg));localStorage.setItem('siteTheme',theme);btn.textContent=theme==='dark'?'Light Theme':'Dark Theme';}btn.addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';applyTheme(theme)});applyTheme(theme)})();</script><script src="signing-app.js" defer></script><div id="umuchat-widget"></div><script src="chat-widget.js" defer></script></body></html>
